import sys, random, json, subprocess
sys.path.insert(0, '/workspace/submission')
import compiler

MINT = 0
def valid_window(w): return isinstance(w, list) and len(w) == 2 and 0 <= w[0] < w[1] <= 10**12

def check_reply(cmd, rep, state):
    st = rep.get('status')
    # structural field checks
    ok_fields = {
        'ok': None,  # depends on op
    }
    op = cmd.get('op') if isinstance(cmd, dict) else None
    if st == 'invalid':
        return set(rep.keys()) == {'status'}
    if st == 'stale':
        return set(rep.keys()) == {'status', 'rev'}
    if st == 'replay':
        return set(rep.keys()) == {'status','id','rev','base_rev','outcome'} and rep['outcome'] in ('prepared','denied')
    if st == 'blocked':
        if set(rep.keys()) != {'status','rev','link','time','used','capacity'}: return False
        # witness: used > capacity at link/time
        return rep['used'] > rep['capacity']
    if st == 'denied':
        if rep.get('kind') == 'capacity':
            if set(rep.keys()) != {'status','id','rev','kind','link','time','used','capacity'}: return False
            return rep['used'] > rep['capacity']
        if rep.get('kind') == 'cut':
            if set(rep.keys()) != {'status','id','rev','kind','cut'}: return False
            S = set(rep['cut'])
            if len(S) != len(rep['cut']): return False
            # validate strict inequality against the prepare request
            return state is not None and check_cut(cmd, rep['cut'])
        return False
    if st == 'prepared':
        if set(rep.keys()) != {'status','id','rev','plan'}: return False
        return check_plan(cmd, rep['plan'])
    if st == 'error':
        return set(rep.keys()) == {'status','code','rev'} and rep['code'] in (
            'NOT_LOADED','ALREADY_LOADED','TIME','REFERENCE','WINDOW','CONFLICT',
            'MISSING','OWNER','GONE','DENIED')
    if st == 'ok':
        if op == 'about':
            return rep == {'status':'ok','protocol':'forest-controller/3'}
        if op == 'load':
            return set(rep.keys()) == {'status','rev','now'}
        if op == 'audit':
            return set(rep.keys()) == {'status','rev','now','leases','samples'} and \
                len(rep['samples']) == len(cmd['at'])
        if op == 'advance':
            return set(rep.keys()) == {'status','rev','now','expired'}
        if op == 'edit':
            return set(rep.keys()) == {'status','rev','cancelled'}
        if op == 'commit':
            return set(rep.keys()) == {'status','id','rev','replay'} and isinstance(rep['replay'], bool)
        if op == 'cancel':
            return set(rep.keys()) == {'status','rev','released'}
    return False

def check_cut(cmd, S):
    state = CUR['graph']
    if state is None: return False
    links, n = state
    parts = dict(cmd['participants'])
    env = {}
    for l, b in cmd['envelope']:
        env[l] = b
    period = cmd['period']
    S = set(S)
    C = set(parts)
    if not (S & C) or not (C - S): return False
    crossing = sum(period*env.get(i,0) for i,(u,v,c) in enumerate(links) if (u in S) != (v in S))
    demand = sum(parts[v] for v in S if v in C)
    return crossing < demand

def check_plan(cmd, plan):
    state = CUR['graph']
    if state is None: return False
    links, n = state
    parts = dict(cmd['participants'])
    env = {}
    for l, b in cmd['envelope']:
        env[l] = b
    return compiler.verify_plan(links, env, cmd['period'], parts, plan)

CUR = {'graph': None}

def gen_trace(rng):
    cmds = []
    if rng.random() < 0.9:
        n = rng.randint(2, 8)
        links = []
        seen = set()
        for _ in range(rng.randint(1, 10)):
            u = rng.randrange(n); v = rng.randrange(n)
            if u == v: continue
            key = (min(u,v), max(u,v))
            if key in seen: continue
            seen.add(key)
            links.append([u, v, rng.randint(0, 12)])
        bookings = []
        for i in range(rng.randint(0, 4)):
            s = rng.randint(0, 20); e = s + rng.randint(1, 15)
            bookings.append({'id': 'b%d' % i, 'owner': 'ow%d' % i,
                             'window': [s, e],
                             'envelope': [[j, rng.randint(1, 3)] for j in rng.sample(range(len(links)), min(len(links), rng.randint(1, 2)))]})
        cmds.append({'op':'load','n':n,'links':links,'bookings':bookings})
        CUR['graph'] = ([(u,v,c) for (u,v,c) in links], n)
    ids = ['p1', 'p2']
    for step in range(rng.randint(1, 30)):
        k = rng.randrange(12)
        if k == 0:
            cmds.append({'op':'about'})
        elif k == 1:
            cmds.append({'op':'audit','at':[rng.randint(0, 40) for _ in range(rng.randint(0, 4))]})
        elif k == 2:
            cmds.append({'op':'advance','time':rng.randint(0, 40)})
        elif k == 3:
            cmds.append({'op':'edit','rev':rng.randint(0, 5),
                         'changes':[[rng.randrange(6), rng.randint(0, 15)] for _ in range(rng.randint(0, 3))],
                         'force':rng.random() < 0.5})
        elif k in (4, 5, 6):
            if CUR['graph'] is None: continue
            links, n = CUR['graph']
            if not links: continue
            npart = rng.randint(2, min(6, n))
            verts = rng.sample(range(n), npart)
            cmds.append({'op':'prepare','id':rng.choice(ids),'owner':rng.choice(['alice','bob']),
                         'window':[rng.randint(0, 30), rng.randint(31, 60)],
                         'period':rng.randint(1, 5),
                         'participants':[[v, rng.randint(0, 6)] for v in verts],
                         'envelope':[[j, rng.randint(1, 6)] for j in rng.sample(range(len(links)), min(len(links), rng.randint(1, 3)))],
                         'rev':rng.randint(0, 5)})
        elif k in (7, 8):
            cmds.append({'op':'commit','id':rng.choice(ids + ['b0']),
                         'owner':rng.choice(['alice','bob']), 'rev':rng.randint(0, 5)})
        else:
            cmds.append({'op':'cancel','id':rng.choice(ids + ['b0']),
                         'owner':rng.choice(['alice','bob']), 'rev':rng.randint(0, 5)})
    return cmds

def main():
    seed = int(sys.argv[1]); N = int(sys.argv[2])
    rng = random.Random(seed)
    bad = 0
    for it in range(N):
        CUR['graph'] = None
        cmds = gen_trace(rng)
        # compute graph state for validation: only the FIRST load defines the graph
        first = None
        for c in cmds:
            if isinstance(c, dict) and c.get('op') == 'load':
                first = c
                break
        if first is not None:
            CUR['graph'] = ([(u,v,c) for (u,v,c) in first['links']], first['n'])
        inp = ''
        for c in cmds:
            inp += (c if isinstance(c, str) else json.dumps(c)) + '\n'
        p = subprocess.run([sys.executable,'-I','-B','/workspace/submission/main.py'],
                           input=inp.encode(), capture_output=True)
        if p.returncode != 0:
            print('CRASH', p.stderr.decode()[-500:]); bad += 1; continue
        reps = [json.loads(l) for l in p.stdout.decode().splitlines()]
        if len(reps) != len(cmds):
            print('COUNT MISMATCH', len(reps), len(cmds)); bad += 1; continue
        for c, r in zip(cmds, reps):
            if isinstance(c, str):
                if r != {'status':'invalid'}:
                    print('STR REPLY', r); bad += 1
                continue
            if not check_reply(c, r, None):
                print('BAD REPLY', json.dumps(c)[:300], '->', json.dumps(r)[:300])
                bad += 1
                if bad > 8: return 1
    print('traces=%d bad=%d' % (N, bad))
    return 1 if bad else 0

sys.exit(main())
